// @Predicate hexchar(c) ::= (48 <= c <= 57) Or (65 <= c <= 70) Or (97 <= c <= 102)

// Value looks a byte up in the table.
//
// @Ensures hexchar(c) -> r < 16
// @Ensures ~hexchar(c) -> r = 255
func Value(c byte) (r byte) {
	return reverse[c]
}

// Valid reports whether every byte of src is a hexadecimal digit.
//
// @Ensures ok <-> Forall k in [0, |src|) : hexchar(src[k])
func Valid(src []byte) (ok bool) {
	// @Invariant 0 <= i <= |src|
	// @Invariant Forall k in [0, i) : hexchar(src[k])
	for i := range src {
		if reverse[src[i]] > 0x0f {
			return false
		}
	}
	return true
}

// ValueWrong claims a value the table does not have.
//
// @Ensures r = 0
func ValueWrong() (r byte) {
	return reverse['a'] // want `postcondition may not hold: r = 0`
}

// digits is a constant string used as a table.
const digits = "0123456789abcdef"

// @Requires v < 16
// @Ensures (v < 10 -> r = 48 + v) And (v >= 10 -> r = 87 + v)
func Digit(v byte) (r byte) {
	return digits[v]
}

// squares is a small table of ints, keyed.
var squares = [5]int{0: 0, 1: 1, 2: 4, 3: 9, 4: 16}

// @Requires 0 <= i < 5
// @Ensures r = i * i
func Square(i int) (r int) {
	return squares[i]
}

// Table is exported, and another package changes it.
var Table = [4]byte{1, 2, 3, 4}

// @Ensures r = 1
func First() (r byte) {
	return Table[0]
}

// inited is changed by init, so it is not a table.
var inited [4]byte

func init() {
	inited[0] = 9
}

// @Ensures True
func Inited() (r byte) {
	return inited[0] // want `cannot verify Inited: inited is assigned at tables.go:\d+; package-level arrays that are changed are not supported yet`
}

// tested is changed by a test of the package.
var tested = [2]byte{1, 2}

// The build of the package with its tests sees the write and refuses
// Tested, which TestTableChangedByTest checks; the build without them,
// which the corpus runs, does not have the write.
//
// @Ensures r = 1
func Tested() (r byte) {
	return tested[0]
}

// buf is a struct that holds a byte array, which a fixed pointer points to.
type buf struct {
	out [4]byte
}

var fixedPointer = &buf{out: [4]byte{1, 2, 3, 4}}

// @Ensures r = 1 And s = 4
func Pointed() (r, s byte) {
	return fixedPointer.out[0], fixedPointer.out[3]
}

// @Ensures r = 2
func PointedWrong() (r byte) {
	return fixedPointer.out[0] // want `postcondition may not hold: r = 2`
}
